/* WG Motors case study: this post's own components. The post's stylesheet loads
   on this page only. Layout, head, body typography and "More from the blog"
   come from the Blog post template; this adds what only this article has. */

/* The article ends with its own CTA box, so the template's inline demo card is off here. */
[data-bz-node="cta-inline"] { display: none; }

/* The article is a flex column (the Blog post template orders its head that way),
   so vertical margins add instead of collapsing as they do in the handoff's
   flow layout. Gaps above headings are the handoff's collapsed values. */
main > article > * + .bz-block--heading .bz-headingblock h2 { margin-top: 16px; }
main > article > * + .bz-block--heading .bz-headingblock h3 { margin-top: 8px; }
main > article > :is([data-bz-node="stats"], [data-bz-node="callout"]) + .bz-block--heading .bz-headingblock h2 { margin-top: 8px; }
main > article > [data-bz-node="facts"] + .bz-block--heading .bz-headingblock h2 { margin-top: 10px; }
main > article > [data-bz-node="steps"] + .bz-block--heading .bz-headingblock h3 { margin-top: 2px; }
main > article h1, main > article .bz-headingblock :is(h2, h3) { text-wrap: balance; }
main > article .bz-text p { text-wrap: pretty; }
/* A site-wide "lede" rule enlarges any paragraph that follows a heading; in this article it stays body size. */
main > article > .bz-block.bz-block--text:not([data-bz-node="post-meta"], [data-bz-node="post-dek"]) .bz-text p { font-size: 17.5px; line-height: 1.72; }
/* A platform rule takes the last paragraph's margin off; the handoff keeps it. */
main > article > .bz-block--text:not([data-bz-node="post-meta"], [data-bz-node="post-dek"]) .bz-text p:last-child { margin-bottom: 22px; }
/* The site-wide h1 size outranks the template's; this article's title is the handoff's. */
main > article .bz-prose h1 { font-size: clamp(30px, 4vw, 52px); line-height: 1.05; letter-spacing: -.025em; margin: 18px 0 0; }
/* "More from the blog" sits on the handoff's 28px gutter. */
[data-bz-node="more"] > .bz-container { padding-inline: 28px; }

/* Bulleted lists: one bold lead-in run inline with the sentence after it. */
main > article [data-bz-node^="ul-"] ul.bz-grid { gap: 11px; margin: 0 0 22px; }
main > article [data-bz-node^="ul-"] .bz-feature__t { display: inline; font-weight: 700; }
main > article [data-bz-node^="ul-"] .bz-feature__d { display: inline; }
main > article [data-bz-node^="ul-"] .bz-feature__t:not(:only-child)::after { content: ' '; }
main > article [data-bz-node^="ul-"] .bz-feature:not(:has(.bz-feature__d)) .bz-feature__t { font-weight: 400; color: var(--bnb-text); }

/* Stat cards */
main > article > [data-bz-node="stats"].bz-block--statBand { margin: 0 0 30px; background: none; color: inherit; padding: 0; }
[data-bz-node="stats"] .bz-band { display: flex; flex-direction: column-reverse; gap: 12px; padding: 0; }
[data-bz-node="stats"] .bz-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin: 0; }
[data-bz-node="stats"] .bz-stat { background: var(--ink); border-radius: 18px; padding: 20px 18px; margin: 0; }
[data-bz-node="stats"] .bz-stat__v { font: 800 30px/1 var(--font-heading); letter-spacing: -.02em; color: var(--volt); white-space: nowrap; margin: 0; }
[data-bz-node="stats"] .bz-stat__l { font: 600 13px/1.35 var(--font-body); color: color-mix(in srgb, #fff 78%, var(--ink)); margin: 10px 0 0; }
[data-bz-node="stats"] .bz-stat:first-child { background: var(--accent-dark); }
[data-bz-node="stats"] .bz-stat:first-child .bz-stat__v { color: #fff; }
[data-bz-node="stats"] .bz-stat:first-child .bz-stat__l { color: color-mix(in srgb, #fff 86%, var(--accent)); }
main > article [data-bz-node="stats"] .bz-band > div { width: 100%; text-align: left; justify-self: stretch; }
main > article [data-bz-node="stats"] .bz-band .bz-band__b { font: 600 13px/1.5 var(--font-body); color: var(--muted); margin: 0; max-width: none; }

/* At a glance */
main > article [data-bz-node="facts"] ul.bz-grid { display: block; gap: 0; margin: 0 0 28px; padding: 0; background: var(--card); border: 1px solid color-mix(in srgb, var(--ink) 10%, transparent); border-radius: 18px; overflow: hidden; }
main > article [data-bz-node="facts"] .bz-feature { display: grid; grid-template-columns: 190px minmax(0, 1fr); gap: 6px 18px; padding: 15px 22px; }
main > article [data-bz-node="facts"] .bz-feature + .bz-feature { border-top: 1px solid color-mix(in srgb, var(--ink) 7%, transparent); }
main > article [data-bz-node="facts"] .bz-feature::before { content: none; }
main > article [data-bz-node="facts"] .bz-feature__t { font: 700 12.5px/1.5 var(--font-body); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); padding-top: 2px; }
main > article [data-bz-node="facts"] .bz-feature__d { font: 500 15.5px/1.5 var(--font-body); color: var(--ink); }

/* Callout */
main > article > [data-bz-node="callout"] { margin: 0 auto 30px; }
[data-bz-node="callout-col"].bz-col--bg-paper { display: flex; gap: 14px; align-items: flex-start; padding: 22px 24px; border: 0; border-radius: 18px; background: color-mix(in srgb, var(--volt) 26%, #fff); }
[data-bz-node="callout-col"]::before { content: '\26A1'; font-size: 20px; line-height: 1.3; }
main > article [data-bz-node="callout-col"].bz-col--bg-paper .bz-text p { font: 400 16px/1.6 var(--font-body) !important; font-style: normal; color: var(--bnb-text) !important; margin: 6px 0 0; }
main > article [data-bz-node="callout-col"].bz-col--bg-paper .bz-text p:first-child { font: 800 16.5px/1.4 var(--font-body) !important; color: var(--ink) !important; margin: 0; }

/* Five-phase timeline */
main > article [data-bz-node="steps"] ul.bz-grid { display: block; gap: 0; margin: 6px 0 28px; padding: 0; counter-reset: bnb-step; }
main > article [data-bz-node="steps"] .bz-feature { display: grid; grid-template-columns: 40px minmax(0, 1fr); column-gap: 16px; position: relative; padding: 0 0 22px; counter-increment: bnb-step; }
main > article [data-bz-node="steps"] .bz-feature:last-child { padding-bottom: 0; }
main > article [data-bz-node="steps"] .bz-feature::before { content: counter(bnb-step); position: static; grid-row: 1 / span 2; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; background: var(--accent-tint); color: var(--accent-dark); font: 800 15px/1 var(--font-body); }
main > article [data-bz-node="steps"] .bz-feature:not(:last-child)::after { content: ''; position: absolute; left: 19px; top: 40px; bottom: 0; width: 2px; background: color-mix(in srgb, var(--accent) 14%, var(--card)); }
main > article [data-bz-node="steps"] .bz-feature__t { grid-column: 2; padding-top: 8px; font: 800 17px/1.4 var(--font-body); color: var(--ink); display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; }
main > article [data-bz-node="steps"] .bz-feature__d { grid-column: 2; font: 400 16px/1.62 var(--font-body); margin-top: 6px; }
.bnb-when { background: color-mix(in srgb, var(--accent) 5%, var(--paper)); color: var(--ink-soft); font: 700 12px/1.3 var(--font-body); padding: 4px 10px; border-radius: 999px; }

/* What was built */
main > article > [data-bz-node="built"] { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin: 0 auto 24px; }
[data-bz-node="built"] > .bz-col { background: var(--card); border: 1px solid color-mix(in srgb, var(--ink) 10%, transparent); border-radius: 18px; padding: 20px 22px; box-shadow: none; grid-column: auto; }
[data-bz-node="built"] .bz-container { padding-inline: 0; }
main > article [data-bz-node="built"] .bz-headingblock h4 { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 0; padding-bottom: 12px; border-bottom: 1px solid var(--line-soft); font: 800 15.5px/1.3 var(--font-body); color: var(--ink); }
.bnb-count { font: 800 22px/1 var(--font-heading); color: var(--accent-dark); }
main > article [data-bz-node="built"] ul.bz-grid { display: grid; gap: 9px; margin: 12px 0 0; padding: 0; }
main > article [data-bz-node="built"] .bz-feature { padding-left: 20px; }
main > article [data-bz-node="built"] .bz-feature::before { content: '\2713'; top: 0; color: var(--accent); font: 800 14.5px/1.45 var(--font-body); }
main > article [data-bz-node="built"] .bz-feature__t { font: 500 14.5px/1.45 var(--font-body); color: var(--bnb-text); }

/* Promised vs delivered */
main > article > [data-bz-node="results-table"] { box-sizing: border-box; width: 100%; max-width: 720px; margin: 0 auto 26px; padding-inline: 28px; }

/* Image slots: a dashed placeholder naming the image still to come. Replace the
   row with an Image block once the file is in the Media Bin. */
main > article > [data-bz-node^="slot-"] { margin: 0 auto 28px; }
main > article [data-bz-node^="slot-"] > .bz-col { aspect-ratio: 16 / 9; display: grid; place-content: center; padding: 20px; text-align: center; border: 2px dashed color-mix(in srgb, var(--ink) 18%, var(--paper)); border-radius: 16px; background: color-mix(in srgb, var(--accent) 3%, var(--paper)); }
main > article [data-bz-node^="slot-"] .bz-container { padding-inline: 0; }
main > article [data-bz-node^="slot-"] .bz-text p { font: 700 15px/1.4 var(--font-body); color: var(--ink-soft); margin: 0; }
main > article [data-bz-node^="slot-"] .bz-text p + p { font: 700 12px/1.3 var(--font-body); letter-spacing: .05em; text-transform: uppercase; color: var(--muted); margin-top: 6px; }

/* The customer's words: one dark card */
main > article > [data-bz-node="testimonial"] { margin: 0 0 28px; }
[data-bz-node="testimonial"] .bz-grid { display: block; }
[data-bz-node="testimonial"] .bz-quote { position: relative; overflow: hidden; display: block; background: var(--ink); border: 0; border-radius: 22px; padding: 32px 34px; box-shadow: none; margin: 0; }
[data-bz-node="testimonial"] .bz-quote::before { content: ''; position: absolute; top: -60px; right: -40px; width: 240px; height: 200px; background: radial-gradient(circle, color-mix(in srgb, var(--accent) 35%, transparent), transparent 70%); }
[data-bz-node="testimonial"] blockquote { position: relative; margin: 0; font: 600 22px/1.38 var(--font-heading); letter-spacing: -.01em; color: #fff; }
[data-bz-node="testimonial"] figcaption { position: relative; margin-top: 18px; }
[data-bz-node="testimonial"] .bz-quote__n { font: 700 14px/1.4 var(--font-body); color: var(--volt); }

[data-bz-node="testimonial"] .bz-stars, [data-bz-node="dealer-quotes"] .bz-stars { display: none; }
/* In the dealer's words: two quote cards */
main > article > [data-bz-node="dealer-quotes"] { margin: 0 0 24px; }
[data-bz-node="dealer-quotes"] .bz-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
[data-bz-node="dealer-quotes"] .bz-quote { display: flex; flex-direction: column; justify-content: space-between; gap: 16px; background: var(--card); border: 1px solid color-mix(in srgb, var(--ink) 10%, transparent); border-radius: 18px; padding: 24px; box-shadow: none; margin: 0; }
[data-bz-node="dealer-quotes"] blockquote { margin: 0; flex: none; font: 600 16.5px/1.55 var(--font-body); color: var(--ink); }
[data-bz-node="dealer-quotes"] figcaption { display: flex; flex-direction: row; align-items: center; justify-content: flex-start; gap: 10px; text-align: left; margin: 0; }
[data-bz-node="dealer-quotes"] figcaption::before { content: 'E'; display: grid; place-items: center; flex: none; width: 34px; height: 34px; border-radius: 50%; background: var(--ink); color: var(--volt); font: 800 13px/1 var(--font-body); }
[data-bz-node="dealer-quotes"] .bz-quote__n { font: 700 13.5px/1.4 var(--font-body); color: var(--ink-soft); }

/* Closing CTA box */
main > article > [data-bz-node="ctabox"] { margin: 8px auto 10px; }
[data-bz-node="ctabox-col"].bz-col--bg-ink { padding: 36px; border-radius: 24px; background: var(--ink); }
[data-bz-node="ctabox-col"]::before { content: ''; position: absolute; top: -50px; right: -20px; width: 260px; height: 200px; background: radial-gradient(circle, color-mix(in srgb, var(--accent) 40%, transparent), transparent 70%); pointer-events: none; }
[data-bz-node="ctabox-col"] > * { position: relative; }
[data-bz-node="ctabox-col"] .bz-container { padding-inline: 0; }
main > article [data-bz-node="ctabox-col"] .bz-headingblock h3 { font: 800 28px/1.1 var(--font-heading); letter-spacing: 0; color: #fff; margin: 0; }
main > article [data-bz-node="ctabox-col"] .bz-block.bz-block--text .bz-text p { font: 500 16px/1.6 var(--font-body); color: color-mix(in srgb, #fff 78%, var(--ink)); margin: 12px 0 0; max-width: 560px; }
main > article [data-bz-node="ctabox-col"] .bz-btns { display: flex; flex-wrap: wrap; gap: 12px; margin: 22px 0 0; }
main > article [data-bz-node="ctabox-col"] .bz-btn { font: 700 15.5px/1.2 var(--font-body); box-shadow: none; }
main > article [data-bz-node="ctabox-col"] .bz-btn--primary { background: var(--volt); color: var(--ink); padding: 14px 26px; }
main > article [data-bz-node="ctabox-col"] .bz-btn--secondary { background: transparent; border: 1.5px solid rgb(255 255 255 / .4); color: #fff; padding: 13px 24px; white-space: normal; }
main > article [data-bz-node="ctabox-col"] .bz-btn--secondary:hover { border-color: #fff; }

/* More from the blog: the category label above each title */
[data-bz-node="more"] .bnb-related-cat { font: 700 12px/1.3 var(--font-body); letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }

@media (max-width: 900px) {
  [data-bz-node="stats"] .bz-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 600px) {
  main > article .bz-container, main > article > .bnb-back, main > article > .bnb-author, main > article > .bz-row, main > article > [data-bz-node="results-table"], main > article > .bz-block:not([data-bz-node]) > .bz-prose { padding-inline: 20px; }
  main > article > .bz-row .bz-container { padding-inline: 0; }
  main > article > .bz-block.bz-block--text:not([data-bz-node="post-meta"], [data-bz-node="post-dek"]) .bz-text p { font-size: 16.5px; }
  main > article [data-bz-node="post-dek"] .bz-text p { font-size: 17.5px; }
  main > article .bz-headingblock h2 { font-size: 25px; }
  [data-bz-node="more"] > .bz-container { padding-inline: 20px; }
  [data-bz-node="stats"] .bz-stat__v { font-size: 26px; }
  main > article [data-bz-node="facts"] .bz-feature { grid-template-columns: 1fr; padding: 14px 18px; }
  main > article > [data-bz-node="built"], [data-bz-node="dealer-quotes"] .bz-grid { grid-template-columns: 1fr; }
  [data-bz-node="testimonial"] .bz-quote { padding: 26px 24px; }
  [data-bz-node="testimonial"] blockquote { font-size: 19px; }
  [data-bz-node="ctabox-col"].bz-col--bg-ink { padding: 28px 24px; }
  main > article [data-bz-node="ctabox-col"] .bz-btn { width: 100%; text-align: center; }
}

