/* WG Motors case study: the parts of the handoff no block field carries. Each
   enhancement is text that is already on the page and readable without it. */
(function () {
  /* The kicker pill. The post's category stays "Case Study" (the blog listing
     reads it); the pill on this page reads as the handoff's kicker. */
  var tag = document.querySelector('[data-bz-node="post-meta"] .bnb-tag');
  if (tag) tag.textContent = 'Buzznerd Case Study · AI Optimization';

  /* "Title · chip" → title + chip, for the timeline months and the counts on
     the two "What was built" cards. */
  function split(selector, cls) {
    Array.prototype.forEach.call(document.querySelectorAll(selector), function (el) {
      var text = el.textContent;
      var at = text.lastIndexOf(' · ');
      if (at < 0) return;
      el.textContent = text.slice(0, at);
      var chip = document.createElement('span');
      chip.className = cls;
      chip.textContent = text.slice(at + 3);
      el.appendChild(chip);
    });
  }
  split('[data-bz-node="steps"] .bz-feature__t', 'bnb-when');
  split('[data-bz-node="built"] .bz-headingblock h4', 'bnb-count');

  /* More from the blog: the three related case studies the handoff names, read
     from their own pages. If any cannot be read the template's cards stay. */
  var grid = document.querySelector('[data-bz-node="more"] .bz-grid');
  if (!grid || !window.fetch || !window.DOMParser) return;
  var base = location.pathname.replace(/\/[^/]+\/?$/, '') || '/blog';
  var slugs = [
    'shaping-a-digital-future-elevating-customer-experiences-at-campbell-supply-company',
    'buzznerd-launches-kriete-truck-centers-ai-powered-digital-store-front-w-hubspot-crm',
    'buzznerd-trucks-launches-new-kenworth-sales-co-website'
  ];
  Promise.all(slugs.map(function (slug) {
    var href = base + '/' + slug;
    return fetch(href, { credentials: 'same-origin' })
      .then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); })
      .then(function (html) {
        var doc = new DOMParser().parseFromString(html, 'text/html');
        var h1 = doc.querySelector('main > article h1');
        var img = doc.querySelector('main > article > .bz-block:not([data-bz-node]) img');
        if (!h1) throw new Error('no title');
        return { href: href, title: h1.textContent.trim(), cover: img ? img.getAttribute('src') : '' };
      });
  })).then(function (posts) {
    grid.textContent = '';
    posts.forEach(function (p) {
      var a = document.createElement('a');
      a.className = 'bz-card bz-post';
      a.href = p.href;
      if (p.cover) {
        var img = document.createElement('img');
        img.src = p.cover;
        img.alt = '';
        img.loading = 'lazy';
        img.decoding = 'async';
        a.appendChild(img);
      }
      var body = document.createElement('div');
      body.className = 'bz-card__body';
      var cat = document.createElement('span');
      cat.className = 'bnb-related-cat';
      cat.textContent = 'Case Study';
      var title = document.createElement('span');
      title.className = 'bz-card__t';
      title.textContent = p.title;
      body.appendChild(cat);
      body.appendChild(title);
      a.appendChild(body);
      grid.appendChild(a);
    });
  }).catch(function () { /* keep the template's newest posts */ });
})();
